    /* -------------------------------------------------------------------------- */
    /*                                    Types                                   */
    /* -------------------------------------------------------------------------- */

    // tag::FacetCutAction[]
    /**
     * @notice Enum for the action to perform on a set of function selectors for a given facet address.
     * @dev Values: Add=0, Replace=1, Remove=2. Stored as uint8 in ABI for FacetCut.action.
     */
    enum FacetCutAction {
        Add,
        Replace,
        Remove
    }

